    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 8;
  if v_state is null then raise exception 'digest-copy recut, corrosion refused: no row for beginner final ord 8'; end if;
